// TEMA 15 — Delitos contra la seguridad vial (arts. 379 a 385 ter CP), omisión del deber de socorro (art. 195 CP)
// y normativa conexa del temario: Ley de Tráfico (RDL 6/2015), Reglamento General de Circulación (RD 1428/2003),
// Orden ICT/155/2020, Orden JUS/1291/2010, Instrucción FGE 3/2006 y Circular FGE 10/2011.
// Formato: o[0] es SIEMPRE la respuesta correcta (la web baraja el orden al mostrarla).
// "f" indica la fuente: texto legal verificado, examen oficial o temario del alumno (contenido técnico/doctrinal).
window.BANCO = window.BANCO || {};
window.BANCO[15] = [
  {"id":"T15-001","p":"¿Dónde se regulan los delitos contra la seguridad vial en el Código Penal?","o":["Libro II, Título XVII, Capítulo IV","Libro II, Título XVI, Capítulo IV","Libro II, Título XVII, Capítulo VI","Libro II, Título XVII, Capítulo II"],"e":"Los delitos contra la seguridad vial forman el Capítulo IV («De los delitos contra la Seguridad Vial») del Título XVII («De los delitos contra la seguridad colectiva») del Libro II.","a":"Libro II, Título XVII, Capítulo IV CP (arts. 379 a 385 ter)","f":"Texto legal"},
  {"id":"T15-002","p":"¿Cómo se denomina el Título XVII del Libro II del Código Penal, en el que se encuentran los delitos contra la seguridad vial?","o":["De los delitos contra la seguridad colectiva","De los delitos contra el orden público","De los delitos contra la seguridad del tráfico","De los delitos contra la Administración pública"],"e":"El Título XVII se denomina «De los delitos contra la seguridad colectiva». Su Capítulo IV es el de la seguridad vial.","a":"Título XVII del Libro II CP","f":"Texto legal"},
  {"id":"T15-003","p":"¿Qué artículos del Código Penal comprenden los delitos contra la seguridad vial?","o":["Del 379 al 385 ter","Del 379 al 385 bis","Del 379 al 385","Del 380 al 385 ter"],"e":"El Capítulo IV del Título XVII va del art. 379 al art. 385 ter.","a":"Arts. 379 a 385 ter CP","f":"Texto legal"},
  {"id":"T15-005","p":"¿En qué Título del Libro II del Código Penal se regula la omisión del deber de socorro (art. 195)?","o":["En el Título IX, «De la omisión del deber de socorro»","En el Título XVII, Capítulo IV, junto a los delitos contra la seguridad vial","En el Título VII, «De las torturas y otros delitos contra la integridad moral»","En el Título XIX, «Delitos contra la Administración pública»"],"e":"La omisión del deber de socorro tiene un título propio: el Título IX del Libro II. No forma parte de los delitos contra la seguridad vial.","a":"Título IX del Libro II CP (art. 195)","f":"Texto legal"},
  {"id":"T15-006","p":"Según el artículo 379.1 CP, comete delito quien conduce un vehículo de motor o ciclomotor en vía urbana a una velocidad superior a la permitida reglamentariamente en:","o":["60 km/h","50 km/h","80 km/h","40 km/h"],"e":"Art. 379.1: velocidad superior en sesenta kilómetros por hora en vía urbana o en ochenta kilómetros por hora en vía interurbana a la permitida reglamentariamente.","a":"Art. 379.1 CP","f":"Texto legal"},
  {"id":"T15-007","p":"Según el artículo 379.1 CP, en vía interurbana es delito superar la velocidad permitida reglamentariamente en:","o":["80 km/h","60 km/h","100 km/h","70 km/h"],"e":"Art. 379.1: 60 km/h por encima en vía urbana y 80 km/h por encima en vía interurbana.","a":"Art. 379.1 CP","f":"Texto legal"},
  {"id":"T15-008","p":"En una vía urbana limitada a 50 km/h se acredita que un turismo circulaba a 111 km/h (velocidad ya corregida con el margen de error del cinemómetro). ¿Qué ha cometido el conductor?","o":["Un delito del artículo 379.1 CP, porque supera en más de 60 km/h el límite","Solo una infracción administrativa, porque no supera el límite en 80 km/h","Un delito del artículo 380 CP","Un delito del artículo 381.2 CP"],"e":"111 − 50 = 61 km/h por encima del límite. En vía urbana el art. 379.1 exige superar en más de 60 km/h la velocidad permitida, así que es delito. El umbral de 80 km/h es para vías interurbanas.","a":"Art. 379.1 CP","f":"Texto legal"},
  {"id":"T15-009","p":"En una autovía limitada a 120 km/h se acredita que un turismo circulaba a 195 km/h (velocidad ya corregida). Sin más datos, ¿qué ha cometido?","o":["No comete el delito del artículo 379.1 CP, porque no supera en más de 80 km/h el límite; sería infracción administrativa","Un delito del artículo 379.1 CP, porque supera en más de 60 km/h el límite","Un delito del artículo 380 CP por conducción temeraria","Un delito del artículo 381.1 CP"],"e":"195 − 120 = 75 km/h. En vía interurbana el art. 379.1 exige superar el límite en más de 80 km/h, así que no llega al delito. Los 60 km/h solo valen para vía urbana.","a":"Art. 379.1 CP","f":"Texto legal"},
  {"id":"T15-010","p":"¿Cuáles son las penas del delito de conducción a velocidad excesiva del artículo 379.1 CP?","o":["Prisión de 3 a 6 meses o multa de 6 a 12 meses o trabajos en beneficio de la comunidad de 31 a 90 días y, en cualquier caso, privación del derecho a conducir por tiempo superior a 1 y hasta 4 años","Prisión de 6 meses a 1 año y privación del derecho a conducir por tiempo superior a 1 y hasta 4 años","Prisión de 3 a 6 meses o multa de 12 a 24 meses o trabajos en beneficio de la comunidad de 31 a 90 días","Prisión de 3 a 6 meses y multa de 6 a 12 meses y privación del derecho a conducir de 1 a 4 años"],"e":"Art. 379.1: prisión de tres a seis meses o multa de seis a doce meses o trabajos en beneficio de la comunidad de treinta y uno a noventa días, y, en cualquier caso, privación del derecho a conducir vehículos a motor y ciclomotores por tiempo superior a uno y hasta cuatro años.","a":"Art. 379.1 CP","f":"Texto legal"},
  {"id":"T15-012","p":"En el artículo 379 CP, las penas de prisión, multa y trabajos en beneficio de la comunidad son:","o":["Alternativas: se impone una de ellas, junto con la privación del derecho a conducir","Acumulativas: se imponen las tres","Alternativas, y la privación del derecho a conducir es también opcional","Acumulativas la prisión y la multa, y alternativos los trabajos en beneficio de la comunidad"],"e":"El art. 379.1 une esas penas con «o» (prisión o multa o trabajos en beneficio de la comunidad) y añade la privación del derecho a conducir «en cualquier caso».","a":"Art. 379.1 CP","f":"Texto legal"},
  {"id":"T15-014","p":"¿Con qué vehículos puede cometerse el delito del artículo 379 CP?","o":["Con un vehículo de motor o un ciclomotor","Con cualquier vehículo, incluidas las bicicletas","Solo con vehículos para los que se exija permiso de conducción de la clase B","Solo con turismos y motocicletas"],"e":"El art. 379 se refiere a quien «condujere un vehículo de motor o un ciclomotor».","a":"Art. 379.1 y 2 CP","f":"Texto legal"},
  {"id":"T15-015","p":"¿Con qué penas castiga el artículo 379.2 CP la conducción bajo la influencia de drogas o bebidas alcohólicas?","o":["Con las mismas penas que el exceso de velocidad del artículo 379.1","Con prisión de 6 meses a 1 año y privación del derecho a conducir de 1 a 4 años","Con prisión de 6 meses a 2 años y privación del derecho a conducir de 1 a 6 años","Con multa de 3 a 12 meses"],"e":"Art. 379.2: «Con las mismas penas será castigado el que condujere…». Es decir, prisión de 3 a 6 meses o multa de 6 a 12 meses o trabajos en beneficio de la comunidad de 31 a 90 días y, en cualquier caso, privación del derecho a conducir por tiempo superior a 1 y hasta 4 años.","a":"Art. 379.2 CP (remite a las penas del 379.1)","f":"Texto legal"},
  {"id":"T15-016","p":"Según el artículo 379.2 CP, en todo caso será condenado quien conduzca con una tasa de alcohol en aire espirado:","o":["Superior a 0,60 mg/l","Superior a 0,50 mg/l","Superior a 0,25 mg/l","Igual o superior a 0,60 mg/l"],"e":"Art. 379.2, segundo inciso: «…con una tasa de alcohol en aire espirado superior a 0,60 miligramos por litro…». Tiene que ser superior, no basta con igual.","a":"Art. 379.2, párrafo segundo, CP","f":"Texto legal"},
  {"id":"T15-017","p":"Según el artículo 379.2 CP, en todo caso será condenado quien conduzca con una tasa de alcohol en sangre:","o":["Superior a 1,2 g/l","Superior a 0,8 g/l","Superior a 0,5 g/l","Superior a 1,5 g/l"],"e":"Art. 379.2: «…o con una tasa de alcohol en sangre superior a 1,2 gramos por litro».","a":"Art. 379.2, párrafo segundo, CP","f":"Texto legal"},
  {"id":"T15-018","p":"¿En qué artículo del Código Penal se castiga la conducción bajo la influencia de drogas tóxicas, estupefacientes, sustancias psicotrópicas o bebidas alcohólicas, o con una tasa de alcohol superior a 0,60 mg/l en aire espirado o 1,2 g/l en sangre?","o":["Artículo 379.2","Artículo 379.1","Artículo 380","Artículo 383"],"e":"Es el art. 379.2. El 379.1 es el exceso de velocidad, el 380 la conducción temeraria y el 383 la negativa a las pruebas.","a":"Art. 379.2 CP","f":"Texto legal"},
  {"id":"T15-019","p":"Un conductor arroja exactamente 0,60 mg/l de alcohol en aire espirado. ¿Se aplica automáticamente el segundo inciso del artículo 379.2 CP?","o":["No, porque exige una tasa superior a 0,60 mg/l; solo habría delito si se acredita que conducía bajo la influencia del alcohol","Sí, porque alcanza la tasa de 0,60 mg/l","Sí, pero como delito del artículo 383 CP","No, porque la tasa penal es superior a 0,80 mg/l"],"e":"El art. 379.2 exige una tasa «superior a 0,60». Con 0,60 exactos no se aplica la condena «en todo caso», pero sí puede haber delito por el primer inciso si se prueba la influencia del alcohol en la conducción.","a":"Art. 379.2 CP","f":"Texto legal"},
  {"id":"T15-020","p":"Según el artículo 379.2 CP, ¿bajo la influencia de qué sustancias se castiga la conducción?","o":["Drogas tóxicas, estupefacientes, sustancias psicotrópicas o bebidas alcohólicas","Bebidas alcohólicas y medicamentos de cualquier tipo","Solo bebidas alcohólicas y estupefacientes","Drogas tóxicas, bebidas alcohólicas y sustancias dopantes"],"e":"Art. 379.2: «…bajo la influencia de drogas tóxicas, estupefacientes, sustancias psicotrópicas o de bebidas alcohólicas».","a":"Art. 379.2, párrafo primero, CP","f":"Texto legal"},
  {"id":"T15-021","p":"Un conductor arroja 0,45 mg/l de alcohol en aire espirado. ¿Puede cometer el delito del artículo 379.2 CP?","o":["Sí, si se acredita que conducía bajo la influencia de bebidas alcohólicas","No, nunca, porque no supera 0,60 mg/l","Sí, siempre, porque supera 0,25 mg/l","Solo si se niega a la segunda prueba"],"e":"El art. 379.2 castiga dos conductas: conducir bajo la influencia del alcohol (primer inciso), con cualquier tasa si se prueba esa influencia, y conducir con más de 0,60 mg/l (segundo inciso), «en todo caso».","a":"Art. 379.2, párrafo primero, CP","f":"Texto legal"},
  {"id":"T15-022","p":"¿Qué significa la expresión «en todo caso» del segundo inciso del artículo 379.2 CP?","o":["Que superada la tasa de 0,60 mg/l (o 1,2 g/l en sangre) hay delito sin necesidad de probar la influencia en la conducción","Que siempre hay que probar la influencia del alcohol, aunque se supere la tasa","Que solo hay delito si además se produce un accidente","Que la pena de prisión es obligatoria"],"e":"El art. 379.2 dice: «En todo caso será condenado con dichas penas el que condujere con una tasa… superior a 0,60 mg/l…». Superar esa tasa basta para cometer el delito.","a":"Art. 379.2, párrafo segundo, CP","f":"Texto legal"},
  {"id":"T15-023","p":"La mera presencia de drogas en el organismo del conductor, sin que se acredite que influyen en la conducción, ¿constituye el delito del artículo 379.2 CP?","o":["No, porque el artículo 379.2 castiga conducir «bajo la influencia» de drogas, y para las drogas no fija ninguna tasa","Sí, porque cualquier presencia de drogas es delito","Sí, si la concentración supera 0,60 mg/l","Sí, pero como delito del artículo 383"],"e":"Para las drogas el art. 379.2 solo castiga conducir «bajo la influencia». Las tasas objetivas del segundo inciso son solo de alcohol.","a":"Art. 379.2 CP","f":"Texto legal"},
  {"id":"T15-024","p":"Un ciclista sin motor circula con una tasa de 0,70 mg/l de alcohol en aire espirado. ¿Comete el delito del artículo 379.2 CP?","o":["No, porque una bicicleta no es un vehículo de motor ni un ciclomotor","Sí, porque supera 0,60 mg/l","Sí, si se ve implicado en un accidente","Sí, pero en la modalidad del artículo 380"],"e":"El art. 379 solo castiga a quien conduce «un vehículo de motor o ciclomotor». Una bicicleta sin motor no lo es, así que no hay delito, aunque sí una infracción administrativa.","a":"Art. 379.2 CP","f":"Texto legal"},
  {"id":"T15-025","p":"El conductor de un ciclomotor arroja 0,70 mg/l de alcohol en aire espirado. ¿Qué ha cometido?","o":["Un delito del artículo 379.2 CP","Solo una infracción administrativa, porque el ciclomotor no es vehículo de motor","Un delito del artículo 384 CP","Un delito del artículo 380 CP"],"e":"El art. 379.2 incluye expresamente el ciclomotor y la tasa supera 0,60 mg/l, así que es delito.","a":"Art. 379.2 CP","f":"Texto legal"},
  {"id":"T15-027","p":"¿Qué tipo de delito es el del artículo 379 CP según la clasificación del artículo 13 CP?","o":["Menos grave","Grave","Leve","Grave o menos grave, según la tasa de alcohol"],"e":"Todas sus penas son menos graves según el art. 33.3: prisión de 3 a 6 meses (de 3 meses a 5 años), multa de 6 a 12 meses (más de 3 meses), trabajos en beneficio de la comunidad de 31 a 90 días (de 31 días a 1 año) y privación del derecho a conducir de más de 1 hasta 4 años (de 1 año y 1 día a 8 años). Por tanto es delito menos grave (art. 13.2).","a":"Arts. 13.2, 33.3 y 379 CP","f":"Texto legal"},
  {"id":"T15-028","p":"Según el artículo 380.1 CP, comete delito quien conduce un vehículo a motor o ciclomotor:","o":["Con temeridad manifiesta y pone en concreto peligro la vida o la integridad de las personas","Con temeridad manifiesta, aunque no ponga en peligro a nadie","Con manifiesto desprecio por la vida de los demás","De forma negligente y causa daños materiales"],"e":"Art. 380.1: «El que condujere un vehículo a motor o un ciclomotor con temeridad manifiesta y pusiere en concreto peligro la vida o la integridad de las personas…».","a":"Art. 380.1 CP","f":"Texto legal"},
  {"id":"T15-029","p":"¿Cuáles son las penas de la conducción temeraria del artículo 380.1 CP?","o":["Prisión de 6 meses a 2 años y privación del derecho a conducir por tiempo superior a 1 y hasta 6 años","Prisión de 6 meses a 1 año y privación del derecho a conducir por tiempo superior a 1 y hasta 6 años","Prisión de 6 meses a 2 años y privación del derecho a conducir por tiempo superior a 1 y hasta 4 años","Prisión de 2 a 5 años, multa de 12 a 24 meses y privación del derecho a conducir de 6 a 10 años"],"e":"Art. 380.1: prisión de seis meses a dos años y privación del derecho a conducir vehículos a motor y ciclomotores por tiempo superior a uno y hasta seis años.","a":"Art. 380.1 CP","f":"Texto legal"},
  {"id":"T15-031","p":"Según el artículo 380.2 CP, se reputará manifiestamente temeraria la conducción en la que concurran las circunstancias previstas en:","o":["El apartado primero y el inciso segundo del apartado segundo del artículo 379","El apartado segundo y el inciso primero del apartado segundo del artículo 379","El inciso segundo del apartado primero del artículo 379","El artículo 383 y el artículo 384"],"e":"Art. 380.2: «…las circunstancias previstas en el apartado primero y en el inciso segundo del apartado segundo del artículo anterior». Es decir, la velocidad penal del 379.1 junto con la tasa penal de alcohol del 379.2 (más de 0,60 mg/l o 1,2 g/l).","a":"Art. 380.2 CP","f":"Texto legal"},
  {"id":"T15-032","p":"Un conductor circula en vía urbana a 65 km/h por encima del límite y con 0,70 mg/l de alcohol en aire espirado. A efectos del artículo 380 CP, esa conducción:","o":["Se reputa manifiestamente temeraria","No puede considerarse temeraria, porque son dos delitos distintos del artículo 379","Solo es temeraria si además supera en 80 km/h el límite","Se considera conducción con manifiesto desprecio por la vida (art. 381.1)"],"e":"Concurren el exceso de velocidad del 379.1 y la tasa superior a 0,60 mg/l del 379.2 (inciso segundo), así que el art. 380.2 la reputa manifiestamente temeraria. Para el delito del 380.1 hace falta además poner en concreto peligro la vida o integridad de las personas.","a":"Art. 380.2 CP","f":"Texto legal"},
  {"id":"T15-035","p":"Según el artículo 381.1 CP, ¿qué añade este delito a la conducta del artículo 380?","o":["Que se realice con manifiesto desprecio por la vida de los demás","Que se conduzca bajo la influencia de bebidas alcohólicas","Que se cause un resultado de muerte","Que se conduzca sin permiso"],"e":"Art. 381.1: castiga a quien, «con manifiesto desprecio por la vida de los demás, realizare la conducta descrita en el artículo anterior».","a":"Art. 381.1 CP","f":"Texto legal"},
  {"id":"T15-036","p":"¿Cuáles son las penas del artículo 381.1 CP?","o":["Prisión de 2 a 5 años, multa de 12 a 24 meses y privación del derecho a conducir de 6 a 10 años","Prisión de 1 a 2 años, multa de 6 a 12 meses y privación del derecho a conducir de 6 a 10 años","Prisión de 6 meses a 2 años y privación del derecho a conducir de 1 a 6 años","Prisión de 2 a 5 años y privación del derecho a conducir por tiempo superior a 1 y hasta 6 años"],"e":"Art. 381.1: prisión de dos a cinco años, multa de doce a veinticuatro meses y privación del derecho a conducir vehículos a motor y ciclomotores durante un período de seis a diez años.","a":"Art. 381.1 CP","f":"Texto legal"},
  {"id":"T15-038","p":"Según el artículo 381.2 CP, si con manifiesto desprecio por la vida de los demás no se hubiere puesto en concreto peligro la vida o la integridad de las personas, las penas serán:","o":["Prisión de 1 a 2 años, multa de 6 a 12 meses y privación del derecho a conducir de 6 a 10 años","Prisión de 2 a 5 años, multa de 12 a 24 meses y privación del derecho a conducir de 6 a 10 años","Prisión de 6 meses a 2 años y privación del derecho a conducir de 1 a 6 años","No hay delito, porque falta el peligro concreto"],"e":"Art. 381.2: prisión de uno a dos años, multa de seis a doce meses y privación del derecho a conducir por el tiempo del párrafo anterior (6 a 10 años).","a":"Art. 381.2 CP","f":"Texto legal"},
  {"id":"T15-040","p":"Un conductor, con manifiesto desprecio por la vida de los demás, conduce de forma manifiestamente temeraria pero sin llegar a poner en concreto peligro a ninguna persona. ¿Qué artículo se aplica?","o":["El artículo 381.2 CP","El artículo 380.1 CP","El artículo 381.1 CP","Ninguno: sin peligro concreto no hay delito"],"e":"Sin peligro concreto no se aplica el 380.1 ni el 381.1, pero el art. 381.2 castiga precisamente ese caso cuando hay manifiesto desprecio por la vida.","a":"Art. 381.2 CP","f":"Texto legal"},
  {"id":"T15-041","p":"Según el artículo 382 CP, cuando con los actos de los artículos 379, 380 y 381 se ocasione además un resultado lesivo constitutivo de delito, los jueces:","o":["Apreciarán tan solo la infracción más gravemente penada, aplicando la pena en su mitad superior","Castigarán ambos delitos por separado, sumando las penas","Apreciarán solo el delito contra la seguridad vial","Aplicarán la pena del resultado lesivo en su mitad inferior"],"e":"Art. 382: «…los Jueces o Tribunales apreciarán tan sólo la infracción más gravemente penada, aplicando la pena en su mitad superior y condenando, en todo caso, al resarcimiento de la responsabilidad civil…».","a":"Art. 382 CP","f":"Texto legal"},
  {"id":"T15-043","p":"Para que se aplique el artículo 382 CP, el resultado lesivo constitutivo de delito debe ser:","o":["Cualquiera que sea su gravedad","Al menos de lesiones graves","Necesariamente la muerte de una persona","Solo de daños materiales superiores a 400 euros"],"e":"Art. 382: «…un resultado lesivo constitutivo de delito, cualquiera que sea su gravedad…».","a":"Art. 382 CP","f":"Texto legal"},
  {"id":"T15-044","p":"Cuando el resultado lesivo concurre con un delito del artículo 381 CP, ¿qué establece especialmente el artículo 382?","o":["Que se impondrá en todo caso la privación del derecho a conducir prevista en el 381 en su mitad superior","Que se impondrá la pena de prisión en su grado máximo","Que no se aplica la regla concursal","Que la privación del derecho a conducir será definitiva"],"e":"Art. 382, último inciso: cuando el resultado lesivo concurra con un delito del art. 381, se impondrá en todo caso la pena de privación del derecho a conducir prevista en este precepto en su mitad superior.","a":"Art. 382 CP","f":"Texto legal"},
  {"id":"T15-047","p":"Según el artículo 382 bis.1 CP, el conductor de un vehículo a motor o ciclomotor que, fuera de los casos del artículo 195, voluntariamente y sin riesgo propio o de terceros, abandone el lugar de los hechos tras causar un accidente con fallecidos o con determinadas lesiones, será castigado:","o":["Como autor de un delito de abandono del lugar del accidente","Como autor de un delito de omisión del deber de socorro","Como autor de un delito de conducción temeraria","Solo con una infracción administrativa muy grave"],"e":"Art. 382 bis.1: será castigado «como autor de un delito de abandono del lugar del accidente». Es un delito distinto de la omisión del deber de socorro (art. 195), que el propio precepto deja fuera.","a":"Art. 382 bis.1 CP","f":"Texto legal"},
  {"id":"T15-048","p":"El artículo 382 bis.1 CP exige que el accidente haya causado el fallecimiento de una o varias personas o alguna de las lesiones de los artículos:","o":["147.1, 149 y 150","147.1, 148 y 149","147.2, 149 y 150","152, 153 y 154"],"e":"Art. 382 bis.1: «…en el que fallecieren una o varias personas o en el que se le causare alguna de las lesiones a que se refieren los artículos 147.1, 149 y 150…».","a":"Art. 382 bis.1 CP","f":"Texto legal"},
  {"id":"T15-049","p":"Si el abandono del lugar del accidente del artículo 382 bis tiene su origen en una acción imprudente del conductor, la pena es:","o":["Prisión de 6 meses a 4 años y privación del derecho a conducir de 1 a 4 años","Prisión de 3 a 6 meses y privación del derecho a conducir de 6 meses a 2 años","Prisión de 6 meses a 18 meses y privación del derecho a conducir de 1 a 4 años","Multa de 3 a 12 meses"],"e":"Art. 382 bis.2: si los hechos tuvieran su origen en una acción imprudente del conductor, prisión de seis meses a cuatro años y privación del derecho a conducir vehículos a motor y ciclomotores de uno a cuatro años.","a":"Art. 382 bis.2 CP","f":"Texto legal"},
  {"id":"T15-050","p":"Si el origen de los hechos que dan lugar al abandono del lugar del accidente (art. 382 bis) fuera fortuito, la pena es:","o":["Prisión de 3 a 6 meses y privación del derecho a conducir de 6 meses a 2 años","Prisión de 6 meses a 4 años y privación del derecho a conducir de 1 a 4 años","Prisión de 6 a 18 meses","Multa de 6 a 12 meses y privación del derecho a conducir de 6 meses a 1 año"],"e":"Art. 382 bis.3: si el origen fuera fortuito, prisión de tres a seis meses y privación del derecho a conducir vehículos a motor y ciclomotores de seis meses a dos años.","a":"Art. 382 bis.3 CP","f":"Texto legal"},
  {"id":"T15-052","p":"¿Cuál de los siguientes es un requisito del delito de abandono del lugar del accidente (art. 382 bis.1 CP)?","o":["Que el conductor abandone el lugar voluntariamente y sin que concurra riesgo propio o de terceros","Que la víctima quede desamparada y en peligro manifiesto y grave","Que el conductor circule bajo la influencia de bebidas alcohólicas","Que el accidente cause daños materiales de cualquier cuantía"],"e":"Art. 382 bis.1: el conductor debe actuar «voluntariamente y sin que concurra riesgo propio o de terceros». Que la víctima esté desamparada y en peligro manifiesto y grave es un elemento del art. 195, no del 382 bis.","a":"Art. 382 bis.1 CP","f":"Texto legal"},
  {"id":"T15-053","p":"El artículo 382 bis.1 CP se aplica:","o":["Fuera de los casos contemplados en el artículo 195 (omisión del deber de socorro)","Solo cuando además se cometa el delito del artículo 195","Siempre junto con el delito del artículo 383","Solo cuando el conductor esté bajo la influencia del alcohol"],"e":"Art. 382 bis.1: «…que, fuera de los casos contemplados en el artículo 195…». Si la conducta encaja en la omisión del deber de socorro, se aplica el 195.","a":"Art. 382 bis.1 CP","f":"Texto legal"},
  {"id":"T15-054","p":"Un conductor causa un accidente que solo produce daños materiales y se marcha voluntariamente sin riesgo para nadie. ¿Comete el delito del artículo 382 bis CP?","o":["No, porque el artículo 382 bis exige fallecimiento o lesiones de los artículos 147.1, 149 o 150","Sí, porque abandona el lugar del accidente","Sí, en su modalidad fortuita","Sí, pero solo si el accidente fue imprudente"],"e":"El art. 382 bis.1 exige un accidente con fallecidos o con lesiones de los arts. 147.1, 149 o 150. Con solo daños materiales no hay este delito.","a":"Art. 382 bis.1 CP","f":"Texto legal"},
  {"id":"T15-055","p":"¿Qué ley orgánica introdujo en el Código Penal el delito de abandono del lugar del accidente (art. 382 bis)?","o":["La Ley Orgánica 2/2019, de 1 de marzo","La Ley Orgánica 11/2022, de 13 de septiembre","La Ley Orgánica 1/2015, de 30 de marzo","La Ley Orgánica 15/2007, de 30 de noviembre"],"e":"El art. 382 bis lo introdujo la LO 2/2019, de 1 de marzo. La LO 11/2022, de 13 de septiembre, solo dio nueva redacción a su apartado 1 (remite ahora directamente a los arts. 147.1, 149 y 150).","a":"Art. 382 bis CP (LO 2/2019; apdo. 1 redactado por LO 11/2022)","f":"Texto legal (BOE-A-2022-14965)"},
  {"id":"T15-056","p":"¿Qué ley orgánica dio la redacción vigente al apartado 1 del artículo 382 bis CP?","o":["La Ley Orgánica 11/2022, de 13 de septiembre","La Ley Orgánica 2/2019, de 1 de marzo","La Ley Orgánica 1/2015, de 30 de marzo","La Ley Orgánica 10/2022, de 6 de septiembre"],"e":"La LO 11/2022, de 13 de septiembre (BOE de 14/09/2022, en vigor desde el 15/09/2022), modificó los arts. 142.2, 152.2 y 382 bis.1 CP.","a":"Art. 382 bis.1 CP (redacción LO 11/2022)","f":"Texto legal (BOE-A-2022-14965)"},
  {"id":"T15-057","p":"Según el artículo 383 CP, comete delito el conductor que:","o":["Requerido por un agente de la autoridad, se niega a someterse a las pruebas legalmente establecidas para comprobar las tasas de alcoholemia y la presencia de drogas","Se niega a mostrar su permiso de conducción a un agente","Da positivo en una prueba de alcoholemia con cualquier tasa","Se niega a firmar la denuncia administrativa"],"e":"Art. 383: «El conductor que, requerido por un agente de la autoridad, se negare a someterse a las pruebas legalmente establecidas para la comprobación de las tasas de alcoholemia y la presencia de las drogas tóxicas, estupefacientes y sustancias psicotrópicas…».","a":"Art. 383 CP","f":"Texto legal"},
  {"id":"T15-058","p":"¿Cuáles son las penas del delito de negativa a someterse a las pruebas del artículo 383 CP?","o":["Prisión de 6 meses a 1 año y privación del derecho a conducir por tiempo superior a 1 y hasta 4 años","Prisión de 6 meses a 2 años y privación del derecho a conducir por tiempo superior a 1 y hasta 4 años","Prisión de 3 a 6 meses o multa de 6 a 12 meses y privación del derecho a conducir de 1 a 4 años","Multa de 3 a 12 meses y privación del derecho a conducir por tiempo superior a 1 y hasta 4 años"],"e":"Art. 383: prisión de seis meses a un año y privación del derecho a conducir vehículos a motor y ciclomotores por tiempo superior a uno y hasta cuatro años.","a":"Art. 383 CP","f":"Texto legal"},
  {"id":"T15-059","p":"Para que exista el delito del artículo 383 CP, el requerimiento para someterse a las pruebas debe hacerlo:","o":["Un agente de la autoridad","Un juez de instrucción","El Ministerio Fiscal","Un facultativo médico"],"e":"Art. 383: el conductor debe ser «requerido por un agente de la autoridad».","a":"Art. 383 CP","f":"Texto legal"},
  {"id":"T15-063","p":"¿Qué artículo del Código Penal castiga al conductor que, requerido por un agente de la autoridad, se niega a someterse a las pruebas de detección de alcohol o drogas?","o":["El artículo 383","El artículo 379.2","El artículo 384","El artículo 556 (desobediencia)"],"e":"La negativa a someterse a las pruebas es un delito específico contra la seguridad vial: el art. 383.","a":"Art. 383 CP","f":"Texto legal"},
  {"id":"T15-064","p":"Un conductor de turismo con claros síntomas de embriaguez se niega a someterse a las pruebas de alcoholemia cuando se lo requiere un agente. Si se acredita la influencia del alcohol en su conducción, ¿qué delitos pueden apreciarse?","o":["El del artículo 383 CP por la negativa y el del artículo 379.2 CP por conducir bajo la influencia","Solo el del artículo 383 CP","Solo el del artículo 379.2 CP","Ninguno, porque sin prueba de alcoholemia no hay tasa"],"e":"Son conductas distintas. La negativa es el delito del art. 383, y conducir bajo la influencia del alcohol (primer inciso del 379.2) puede probarse por otros medios, como los síntomas o la forma de conducir, aunque no haya tasa.","a":"Arts. 379.2 y 383 CP","f":"Texto legal"},
  {"id":"T15-065","p":"Según el artículo 384 CP, es delito conducir un vehículo de motor o ciclomotor en los casos de pérdida de vigencia del permiso o licencia por:","o":["Pérdida total de los puntos asignados legalmente","Caducidad del permiso por no haberlo renovado","Pérdida parcial de puntos","No llevar el permiso encima"],"e":"Art. 384, párrafo primero: «…en los casos de pérdida de vigencia del permiso o licencia por pérdida total de los puntos asignados legalmente…».","a":"Art. 384, párrafo primero, CP","f":"Texto legal"},
  {"id":"T15-066","p":"¿Cuáles son las penas del delito del artículo 384 CP?","o":["Prisión de 3 a 6 meses o multa de 12 a 24 meses o trabajos en beneficio de la comunidad de 31 a 90 días","Prisión de 3 a 6 meses o multa de 6 a 12 meses o trabajos en beneficio de la comunidad de 31 a 90 días, y privación del derecho a conducir de 1 a 4 años","Prisión de 6 meses a 1 año y privación del derecho a conducir de 1 a 4 años","Prisión de 6 meses a 2 años o multa de 12 a 24 meses"],"e":"Art. 384: prisión de tres a seis meses o multa de doce a veinticuatro meses o trabajos en beneficio de la comunidad de treinta y uno a noventa días.","a":"Art. 384 CP","f":"Texto legal"},
  {"id":"T15-067","p":"¿Cuál de las siguientes penas NO está prevista en el artículo 384 CP (conducción sin permiso)?","o":["La privación del derecho a conducir vehículos a motor y ciclomotores","La prisión de 3 a 6 meses","La multa de 12 a 24 meses","Los trabajos en beneficio de la comunidad de 31 a 90 días"],"e":"El art. 384 no incluye la privación del derecho a conducir: sus penas son prisión de 3 a 6 meses o multa de 12 a 24 meses o trabajos en beneficio de la comunidad de 31 a 90 días.","a":"Art. 384 CP","f":"Texto legal"},
  {"id":"T15-068","p":"Conducir un vehículo de motor tras haber sido privado cautelarmente del permiso por decisión judicial:","o":["Es delito del artículo 384 CP","Es delito de desobediencia del artículo 556 CP","Es solo infracción administrativa","Es delito del artículo 383 CP"],"e":"Art. 384, párrafo segundo: «La misma pena se impondrá al que realizare la conducción tras haber sido privado cautelar o definitivamente del permiso o licencia por decisión judicial…».","a":"Art. 384, párrafo segundo, CP","f":"Texto legal"},
  {"id":"T15-069","p":"Conducir un ciclomotor sin haber obtenido nunca permiso o licencia de conducción:","o":["Es delito del artículo 384 CP","Es solo infracción administrativa, porque se trata de un ciclomotor","Es delito del artículo 379 CP","Es delito del artículo 385 CP"],"e":"Art. 384, párrafo segundo: también se castiga a quien «condujere un vehículo de motor o ciclomotor sin haber obtenido nunca permiso o licencia de conducción».","a":"Art. 384, párrafo segundo, CP","f":"Texto legal"},
  {"id":"T15-070","p":"¿Qué supuestos castiga el artículo 384 CP?","o":["Pérdida de vigencia por pérdida total de puntos, privación judicial cautelar o definitiva, y no haber obtenido nunca permiso o licencia","Solo la pérdida total de puntos","Solo la privación judicial definitiva del permiso","La conducción con el permiso caducado y la conducción sin seguro obligatorio"],"e":"El art. 384 recoge tres supuestos: pérdida de vigencia por pérdida total de los puntos (párrafo primero), conducción tras privación judicial cautelar o definitiva y conducción sin haber obtenido nunca permiso o licencia (párrafo segundo).","a":"Art. 384 CP","f":"Texto legal"},
  {"id":"T15-074","p":"Según el artículo 385 CP, ¿cuál de las siguientes es una forma de originar un grave riesgo para la circulación?","o":["Colocar en la vía obstáculos imprevisibles, derramar sustancias deslizantes o inflamables, o mutar, sustraer o anular la señalización","Conducir a velocidad superior a la permitida reglamentariamente","Estacionar en doble fila en vía urbana","Circular sin alumbrado de noche"],"e":"Art. 385.1.ª: «Colocando en la vía obstáculos imprevisibles, derramando sustancias deslizantes o inflamables o mutando, sustrayendo o anulando la señalización o por cualquier otro medio».","a":"Art. 385, circunstancia 1.ª, CP","f":"Texto legal"},
  {"id":"T15-075","p":"Según el artículo 385.2.ª CP, también origina un grave riesgo para la circulación quien:","o":["No restablece la seguridad de la vía, cuando haya obligación de hacerlo","No auxilia a la víctima de un accidente","No señaliza su vehículo averiado con los triángulos","No comunica un accidente a la autoridad"],"e":"Art. 385.2.ª: «No restableciendo la seguridad de la vía, cuando haya obligación de hacerlo».","a":"Art. 385, circunstancia 2.ª, CP","f":"Texto legal"},
  {"id":"T15-076","p":"¿Cuáles son las penas del delito de grave riesgo para la circulación del artículo 385 CP?","o":["Prisión de 6 meses a 2 años o multa de 12 a 24 meses y trabajos en beneficio de la comunidad de 10 a 40 días","Prisión de 6 meses a 2 años y multa de 12 a 24 meses, o trabajos en beneficio de la comunidad de 1 a 40 días","Prisión de 3 a 6 meses o multa de 6 a 12 meses y privación del derecho a conducir de 1 a 4 años","Prisión de 6 meses a 1 año y privación del derecho a conducir de 1 a 4 años"],"e":"Art. 385: prisión de seis meses a dos años o multa de doce a veinticuatro meses y trabajos en beneficio de la comunidad de diez a cuarenta días.","a":"Art. 385 CP","f":"Texto legal"},
  {"id":"T15-078","p":"¿Exige el artículo 385 CP que el autor sea conductor de un vehículo a motor o ciclomotor?","o":["No: castiga a «el que originare» un grave riesgo para la circulación, sea o no conductor","Sí, como todos los delitos contra la seguridad vial","Sí, aunque basta con conducir un ciclomotor","Solo en la modalidad de no restablecer la seguridad de la vía"],"e":"El art. 385 empieza «el que originare un grave riesgo para la circulación…», sin exigir conducir. En cambio, los arts. 379, 380, 381, 382 bis, 383 y 384 se refieren al que conduce o al conductor.","a":"Art. 385 CP","f":"Texto legal"},
  {"id":"T15-079","p":"Una persona arranca una señal de «STOP» de un cruce y origina con ello un grave riesgo para la circulación. ¿Qué delito comete?","o":["El del artículo 385 CP, por sustraer la señalización","El del artículo 384 CP","El del artículo 380 CP","Ninguno: es solo infracción administrativa por no ser conductor"],"e":"El art. 385.1.ª castiga originar un grave riesgo para la circulación «mutando, sustrayendo o anulando la señalización». No hace falta ser conductor.","a":"Art. 385, circunstancia 1.ª, CP","f":"Texto legal"},
  {"id":"T15-081","p":"Según el artículo 385 bis CP, el vehículo a motor o ciclomotor utilizado en los delitos contra la seguridad vial se considerará:","o":["Instrumento del delito a los efectos de los artículos 127 y 128","Efecto del delito a los efectos del artículo 129","Prueba del delito que debe depositarse en el juzgado","Bien embargable para la responsabilidad civil"],"e":"Art. 385 bis: «El vehículo a motor o ciclomotor utilizado en los hechos previstos en este Capítulo se considerará instrumento del delito a los efectos de los artículos 127 y 128».","a":"Art. 385 bis CP","f":"Texto legal"},
  {"id":"T15-083","p":"Según el artículo 385 ter CP, ¿en qué delitos puede el juez o tribunal rebajar en un grado la pena de prisión?","o":["En los de los artículos 379, 383, 384 y 385","En los de los artículos 379, 380, 381 y 385","En todos los delitos contra la seguridad vial","En los de los artículos 380, 381 y 382 bis"],"e":"Art. 385 ter: «En los delitos previstos en los artículos 379, 383, 384 y 385, el Juez o Tribunal, razonándolo en sentencia, podrá rebajar en un grado la pena de prisión…».","a":"Art. 385 ter CP","f":"Texto legal"},
  {"id":"T15-084","p":"Según el artículo 385 ter CP, el juez puede rebajar la pena de prisión:","o":["En un grado, razonándolo en sentencia, en atención a la menor entidad del riesgo causado y a las demás circunstancias del hecho","En dos grados, si el acusado reconoce los hechos","En un grado, solo si el acusado repara el daño","En la mitad, si no hay antecedentes penales"],"e":"Art. 385 ter: rebaja «en un grado la pena de prisión en atención a la menor entidad del riesgo causado y a las demás circunstancias del hecho», razonándolo en sentencia.","a":"Art. 385 ter CP","f":"Texto legal"},
  {"id":"T15-085","p":"¿En cuál de los siguientes delitos NO puede aplicarse la rebaja en un grado de la pena de prisión del artículo 385 ter CP?","o":["En la conducción temeraria del artículo 380","En la conducción bajo la influencia del alcohol del artículo 379.2","En la negativa a las pruebas del artículo 383","En la creación de grave riesgo del artículo 385"],"e":"El art. 385 ter solo menciona los arts. 379, 383, 384 y 385. No incluye el 380, el 381 ni el 382 bis.","a":"Art. 385 ter CP","f":"Texto legal"},
  {"id":"T15-087","p":"Según el artículo 195.1 CP, ¿con qué pena se castiga a quien no socorre a una persona desamparada y en peligro manifiesto y grave, pudiendo hacerlo sin riesgo propio ni de terceros?","o":["Multa de 3 a 12 meses","Prisión de 6 meses a 18 meses","Prisión de 6 meses a 4 años","Multa de 6 a 12 meses"],"e":"Art. 195.1: «…será castigado con la pena de multa de tres a doce meses».","a":"Art. 195.1 CP","f":"Texto legal"},
  {"id":"T15-088","p":"Según el artículo 195.2 CP, en las mismas penas del apartado 1 incurre quien:","o":["Impedido de prestar socorro, no demande con urgencia auxilio ajeno","Preste un socorro insuficiente","Abandone el lugar del accidente tras causarlo","Se niegue a declarar como testigo del accidente"],"e":"Art. 195.2: «En las mismas penas incurrirá el que, impedido de prestar socorro, no demande con urgencia auxilio ajeno».","a":"Art. 195.2 CP","f":"Texto legal"},
  {"id":"T15-089","p":"Según el artículo 195.3 CP, si la víctima lo fuere por un accidente ocasionado fortuitamente por quien omitió el auxilio, la pena será de:","o":["Prisión de 6 a 18 meses","Prisión de 6 meses a 4 años","Multa de 3 a 12 meses","Prisión de 3 a 6 meses"],"e":"Art. 195.3: si el accidente fue fortuito, prisión de seis meses a 18 meses.","a":"Art. 195.3 CP","f":"Texto legal"},
  {"id":"T15-090","p":"Según el artículo 195.3 CP, si el accidente que causó la situación de la víctima se debió a imprudencia de quien omitió el auxilio, la pena será de:","o":["Prisión de 6 meses a 4 años","Prisión de 6 a 18 meses","Prisión de 1 a 4 años","Multa de 12 a 24 meses"],"e":"Art. 195.3: si el accidente se debiere a imprudencia, prisión de seis meses a cuatro años.","a":"Art. 195.3 CP","f":"Texto legal"},
  {"id":"T15-091","p":"¿Qué requisitos exige el artículo 195.1 CP respecto de la persona que necesita socorro y de quien omite?","o":["Que esté desamparada y en peligro manifiesto y grave, y que se pueda socorrer sin riesgo propio ni de terceros","Que haya resultado herida en un accidente de tráfico causado por quien omite","Que lo solicite expresamente y que quien omite sea conductor","Que esté inconsciente y que quien omite sea agente de la autoridad"],"e":"Art. 195.1: «El que no socorriere a una persona que se halle desamparada y en peligro manifiesto y grave, cuando pudiere hacerlo sin riesgo propio ni de terceros…».","a":"Art. 195.1 CP","f":"Texto legal"},
  {"id":"T15-097","p":"¿Cuál de los siguientes delitos contra la seguridad vial tiene la pena de privación del derecho a conducir más larga?","o":["El del artículo 381 (de 6 a 10 años)","El del artículo 380 (más de 1 y hasta 6 años)","El del artículo 379 (más de 1 y hasta 4 años)","El del artículo 383 (más de 1 y hasta 4 años)"],"e":"Privación del derecho a conducir: art. 381, de 6 a 10 años; art. 380, más de 1 hasta 6; arts. 379 y 383, más de 1 hasta 4; art. 382 bis, de 1 a 4 (imprudente) o de 6 meses a 2 años (fortuito).","a":"Arts. 379, 380, 381 y 383 CP","f":"Texto legal"},
  {"id":"T15-098","p":"¿En cuál de los siguientes delitos contra la seguridad vial NO hay pena de privación del derecho a conducir vehículos a motor y ciclomotores?","o":["En el del artículo 384 (conducción sin permiso)","En el del artículo 383 (negativa a las pruebas)","En el del artículo 380 (conducción temeraria)","En el del artículo 382 bis (abandono del lugar del accidente)"],"e":"El art. 384 no prevé privación del derecho a conducir (tampoco el 385). Los arts. 379, 380, 381, 382 bis y 383 sí la incluyen.","a":"Art. 384 CP","f":"Texto legal"},
  {"id":"T15-101","p":"Según el artículo 14.1 de la Ley de Tráfico (RDL 6/2015), ¿qué excepción existe a la prohibición de circular con presencia de drogas en el organismo?","o":["Las sustancias utilizadas bajo prescripción facultativa y con finalidad terapéutica, siempre que el conductor esté en condiciones de utilizar el vehículo con la diligencia debida","Ninguna: cualquier presencia de drogas está prohibida","Las drogas consumidas más de 24 horas antes","Las sustancias cuya concentración no supere 0,60 mg/l"],"e":"El art. 14.1 LSV prohíbe circular con presencia de drogas en el organismo, pero excluye las sustancias usadas bajo prescripción facultativa y con finalidad terapéutica, siempre que el conductor pueda conducir con la diligencia exigible.","a":"Art. 14.1 Ley de Tráfico (RDL 6/2015)","f":"Texto legal (RDL 6/2015)"},
  {"id":"T15-102","p":"Según el artículo 14.1 de la Ley de Tráfico, ¿qué tasa de alcohol pueden tener los conductores menores de edad?","o":["0 g/l en sangre y 0 mg/l en aire espirado","0,3 g/l en sangre y 0,15 mg/l en aire espirado","0,5 g/l en sangre y 0,25 mg/l en aire espirado","0,2 g/l en sangre y 0,1 mg/l en aire espirado"],"e":"El art. 14.1 LSV fija para los conductores menores de edad una tasa de alcohol de 0 g/l en sangre y 0 mg/l en aire espirado.","a":"Art. 14.1 Ley de Tráfico (RDL 6/2015)","f":"Texto legal (RDL 6/2015)"},
  {"id":"T15-103","p":"Según el artículo 14.2 de la Ley de Tráfico, ¿quiénes están obligados a someterse a las pruebas de detección de alcohol y drogas?","o":["El conductor y los demás usuarios de la vía implicados en un accidente o que hayan cometido una infracción","Solo los conductores de vehículos a motor","Solo los conductores implicados en un accidente con víctimas","Solo los conductores con síntomas evidentes de embriaguez"],"e":"El art. 14.2 LSV obliga al conductor a someterse a las pruebas que realicen los agentes, y también a los demás usuarios de la vía implicados en un accidente o que hayan cometido una infracción.","a":"Art. 14.2 Ley de Tráfico (RDL 6/2015)","f":"Texto legal (RDL 6/2015)"},
  {"id":"T15-104","p":"Según el artículo 14.3 de la Ley de Tráfico, ¿en qué consisten las pruebas para detectar la presencia de drogas en el organismo?","o":["En una prueba salival con un dispositivo autorizado y un posterior análisis de una muestra salival en cantidad suficiente","En un análisis de sangre obligatorio en un centro sanitario","En la verificación del aire espirado con un etilómetro","Solo en el reconocimiento médico por un médico forense"],"e":"Art. 14.3 LSV: para las drogas, prueba salival mediante dispositivo autorizado y posterior análisis de una muestra salival en cantidad suficiente. Para el alcohol, verificación del aire espirado mediante dispositivos autorizados.","a":"Art. 14.3 Ley de Tráfico (RDL 6/2015)","f":"Texto legal (RDL 6/2015)"},
  {"id":"T15-105","p":"Si no se puede acreditar que las drogas influyen en la conducción, conducir un turismo con presencia de drogas en el organismo constituye:","o":["Una infracción administrativa muy grave del artículo 77.c) de la Ley de Tráfico","Un delito del artículo 379.2 CP","Una infracción administrativa grave del artículo 76","Un delito del artículo 383 CP"],"e":"El art. 77.c) LSV califica como muy grave conducir con tasas de alcohol superiores a las reglamentarias o con presencia de drogas en el organismo. Sin influencia acreditada no hay delito del 379.2.","a":"Art. 77.c) Ley de Tráfico (RDL 6/2015)","f":"Texto legal (RDL 6/2015)"},
  {"id":"T15-106","p":"¿Con qué multa se sanciona la infracción de conducir con presencia de drogas en el organismo (art. 77.c LSV)?","o":["1.000 euros","500 euros","6.000 euros","Entre 3.000 y 20.000 euros"],"e":"Art. 80.2 LSV: las infracciones del art. 77.c) y d) se sancionan con multa de 1.000 euros. Además, conducir con presencia de drogas supone la pérdida de 6 puntos (anexo II).","a":"Arts. 77.c) y 80.2 Ley de Tráfico; anexo II (6 puntos)","f":"Texto legal (RDL 6/2015) y DGT"},
  {"id":"T15-107","p":"Un ciclista implicado en un accidente se niega a someterse a la prueba de alcoholemia que le requiere un agente. ¿Qué comete?","o":["Una infracción administrativa muy grave del artículo 77.d) de la Ley de Tráfico","Un delito del artículo 383 CP","Un delito de desobediencia grave","Nada, porque los ciclistas no están obligados a las pruebas"],"e":"El delito del art. 383 CP solo puede cometerlo el conductor de un vehículo de motor o ciclomotor, como el resto del capítulo; así lo recoge tu temario. Pero el art. 14.2 LSV obliga también a los usuarios implicados en un accidente, y el art. 77.d) LSV castiga como muy grave incumplir esa obligación.","a":"Arts. 14.2 y 77.d) Ley de Tráfico (RDL 6/2015)","f":"Texto legal (RDL 6/2015)"},
  {"id":"T15-108","p":"Según la Ley de Tráfico, la conducción temeraria y la conducción negligente son, respectivamente:","o":["Infracción muy grave (art. 77.e) e infracción grave (art. 76.m)","Infracción grave (art. 76.m) e infracción leve (art. 75)","Delito del art. 380 CP e infracción muy grave","Ambas infracciones muy graves del art. 77"],"e":"Art. 77.e) LSV: «Conducción temeraria» (muy grave). Art. 76.m) LSV: «Conducción negligente» (grave). Solo hay delito del art. 380 CP si la temeridad es manifiesta y se pone en concreto peligro la vida o la integridad de las personas.","a":"Arts. 76.m) y 77.e) Ley de Tráfico (RDL 6/2015)","f":"Texto legal (RDL 6/2015)"},
  {"id":"T15-109","p":"Conducir un vehículo que tiene instalado un inhibidor de radar (art. 77.h LSV) se sanciona con:","o":["Multa de 6.000 euros y pérdida de 6 puntos","Multa de 1.000 euros y pérdida de 6 puntos","Multa de entre 3.000 y 20.000 euros","Multa de 500 euros y pérdida de 4 puntos"],"e":"Art. 80.2 LSV: la infracción del art. 77.h) se sanciona con multa de 6.000 euros. El anexo II prevé la pérdida de 6 puntos por llevar inhibidores de radares o cinemómetros.","a":"Arts. 77.h) y 80.2 Ley de Tráfico; anexo II","f":"Texto legal (RDL 6/2015) y DGT"},
  {"id":"T15-110","p":"Instalar inhibidores de radares o cinemómetros en los vehículos (art. 77.p LSV) se sanciona con:","o":["Multa de entre 3.000 y 20.000 euros","Multa de 6.000 euros","Multa de 1.000 euros","Multa de 500 euros"],"e":"Art. 80.2 LSV: las infracciones del art. 77 n), ñ), o), p), q), r) y t) se sancionan con multa de entre 3.000 y 20.000 euros. Conducir con el inhibidor instalado (77.h) son 6.000 euros.","a":"Arts. 77.p) y 80.2 Ley de Tráfico (RDL 6/2015)","f":"Texto legal (RDL 6/2015)"},
  {"id":"T15-111","p":"Cuando un conductor pierde la totalidad de los puntos, ¿qué organismo declara la pérdida de vigencia de su permiso?","o":["El organismo autónomo Jefatura Central de Tráfico","El Alcalde del municipio donde se cometió la última infracción","El juez de lo penal","La Delegación del Gobierno"],"e":"Art. 71.1 LSV: la Jefatura Central de Tráfico declara la pérdida de vigencia cuando el titular ha perdido la totalidad de los puntos por aplicación del baremo de los anexos II y IV.","a":"Art. 71.1 Ley de Tráfico (RDL 6/2015)","f":"Texto legal (RDL 6/2015)"},
  {"id":"T15-112","p":"Una vez constatada la pérdida total de los puntos, ¿en qué plazo notifica la Administración al interesado el acuerdo de pérdida de vigencia?","o":["15 días","10 días","1 mes","20 días naturales"],"e":"Art. 71.1 LSV: la Administración notificará al interesado, en el plazo de quince días, el acuerdo que declara la pérdida de vigencia.","a":"Art. 71.1 Ley de Tráfico (RDL 6/2015)","f":"Texto legal (RDL 6/2015)"},
  {"id":"T15-113","p":"Tras la pérdida de vigencia por pérdida total de puntos, ¿cuándo puede el titular obtener un nuevo permiso, con carácter general?","o":["Transcurridos 6 meses desde la notificación (3 meses para conductores profesionales)","Transcurrido 1 año desde la notificación","Inmediatamente, si supera el curso de reeducación","Transcurridos 2 años desde la última infracción"],"e":"Art. 71.1 LSV: seis meses desde la notificación del acuerdo (tres meses para profesionales). Si vuelve a perder todos los puntos en los tres años siguientes, el plazo es de doce meses (seis para profesionales). Además debe superar el curso de sensibilización y reeducación vial y las pruebas reglamentarias (art. 71.2).","a":"Art. 71.1 y 2 Ley de Tráfico (RDL 6/2015)","f":"Texto legal (RDL 6/2015)"},
  {"id":"T15-114","p":"Según el artículo 20 del Reglamento General de Circulación, la tasa máxima de alcohol con carácter general es:","o":["0,5 g/l en sangre o 0,25 mg/l en aire espirado","0,3 g/l en sangre o 0,15 mg/l en aire espirado","1,2 g/l en sangre o 0,60 mg/l en aire espirado","0,8 g/l en sangre o 0,40 mg/l en aire espirado"],"e":"Art. 20 RGC: no se puede circular con una tasa de alcohol en sangre superior a 0,5 g/l ni en aire espirado superior a 0,25 mg/l. Las tasas de 0,60 mg/l y 1,2 g/l son las penales del art. 379.2 CP.","a":"Art. 20 Reglamento General de Circulación","f":"Texto legal (RD 1428/2003)"},
  {"id":"T15-115","p":"Según el artículo 20 del Reglamento General de Circulación, ¿a qué conductores se aplica la tasa reducida de 0,3 g/l en sangre (0,15 mg/l en aire espirado)?","o":["A los profesionales (vehículos de más de 3.500 kg, viajeros de más de 9 plazas, servicio público, transporte escolar, mercancías peligrosas, urgencias o transportes especiales) y a los conductores durante los dos años siguientes a obtener el permiso","Solo a los conductores menores de 21 años","A todos los conductores de ciclomotores","Solo a los conductores de vehículos de urgencia"],"e":"Art. 20 RGC: la tasa de 0,3 g/l en sangre (0,15 mg/l en aire) se aplica a los conductores de esos vehículos y a cualquier conductor durante los dos años siguientes a la obtención del permiso o licencia.","a":"Art. 20 Reglamento General de Circulación","f":"Texto legal (RD 1428/2003)"},
  {"id":"T15-116","p":"¿Cuál de las siguientes personas NO aparece en el artículo 21 del Reglamento General de Circulación como obligada a someterse a las pruebas de alcoholemia?","o":["El propietario del vehículo que no lo conducía ni estaba implicado en los hechos","El usuario de la vía implicado directamente como posible responsable en un accidente de circulación","Quien conduzca con síntomas evidentes de estar bajo la influencia de bebidas alcohólicas","El conductor requerido en un control preventivo de alcoholemia ordenado por la autoridad"],"e":"Art. 21 RGC: están obligados a) los implicados como posibles responsables en un accidente; b) quienes conduzcan con síntomas evidentes; c) los conductores denunciados por alguna infracción del reglamento; d) los requeridos en controles preventivos.","a":"Art. 21 Reglamento General de Circulación","f":"Texto legal (RD 1428/2003)"},
  {"id":"T15-117","p":"Según el artículo 23 del Reglamento General de Circulación, ¿qué tiempo mínimo debe transcurrir entre la primera y la segunda prueba de alcoholemia en aire espirado?","o":["10 minutos","5 minutos","15 minutos","30 minutos"],"e":"Art. 23 RGC: entre la primera y la segunda prueba debe pasar un tiempo mínimo de 10 minutos.","a":"Art. 23 Reglamento General de Circulación","f":"Texto legal (RD 1428/2003)"},
  {"id":"T15-118","p":"Según el Reglamento General de Circulación, ¿cómo puede el interesado contrastar los resultados de las pruebas de alcoholemia y quién paga ese contraste si resulta positivo?","o":["Mediante análisis de sangre, orina u otros análogos; si es positivo lo paga el interesado con el depósito que ha adelantado","Solo con una segunda prueba de etilómetro, gratuita en todo caso","Mediante análisis de sangre, que paga siempre la Administración","Mediante prueba salival, que paga el interesado solo si es negativo"],"e":"Arts. 22 y 23 RGC: el contraste puede hacerse con análisis de sangre, orina u otros análogos. El interesado deposita el importe por adelantado. Si el resultado es positivo, lo paga con ese depósito; si es negativo, lo paga la Administración y se le devuelve el depósito.","a":"Arts. 22 y 23 Reglamento General de Circulación","f":"Texto legal (RD 1428/2003)"},
  {"id":"T15-119","p":"Según el artículo 25 del Reglamento General de Circulación, si el resultado de la prueba de alcoholemia es positivo, el agente:","o":["Puede inmovilizar el vehículo, salvo que pueda conducirlo otra persona habilitada","Debe retirar el vehículo al depósito en todo caso","Debe retirar el permiso de conducción durante 3 meses","No puede adoptar ninguna medida sobre el vehículo"],"e":"Art. 25 RGC: el agente puede inmovilizar el vehículo (mediante precinto u otro procedimiento eficaz), salvo que otra persona habilitada pueda hacerse cargo de su conducción. También puede inmovilizarlo si el conductor se niega a las pruebas. Los gastos corren a cargo del conductor.","a":"Art. 25 Reglamento General de Circulación","f":"Texto legal (RD 1428/2003)"},
  {"id":"T15-120","p":"La Orden ICT/155/2020, que regula el control metrológico de los instrumentos de medida, dedica a los cinemómetros y a los etilómetros, respectivamente:","o":["El anexo XII y el anexo XIII","El anexo XIII y el anexo XII","El anexo II y el anexo IV","El anexo I y el anexo II"],"e":"Orden ICT/155/2020: el anexo XII regula los instrumentos que miden la velocidad de los vehículos a motor (cinemómetros) y el anexo XIII los que miden la concentración de alcohol en el aire espirado (etilómetros). Está en vigor desde el 24/10/2020.","a":"Orden ICT/155/2020, anexos XII y XIII","f":"Norma: Orden ICT/155/2020"},
  {"id":"T15-121","p":"Según la Orden ICT/155/2020, ¿qué error máximo permitido se aplica en servicio (verificación periódica) a un cinemómetro de instalación fija o estática que mide una velocidad superior a 100 km/h?","o":["5 %","7 %","3 %","10 %"],"e":"Errores máximos en verificación periódica: instalación fija o estática, 5 km/h hasta 100 km/h y 5 % por encima; instalación móvil, 7 km/h y 7 %; cinemómetro de tramo, 3 km/h y 3 %.","a":"Orden ICT/155/2020, anexo XII","f":"Norma: Orden ICT/155/2020"},
  {"id":"T15-122","p":"Un radar colocado sobre un trípode o en un vehículo policial parado, a efectos del error máximo permitido, se considera:","o":["De instalación estática (5 km/h o 5 %), porque no mide en movimiento","De instalación móvil (7 km/h o 7 %), porque su ubicación cambia","De tramo (3 %)","De instalación móvil solo si es de tecnología láser"],"e":"Según el Tribunal Supremo (Sala de lo Penal), el margen de radar móvil (7 %) solo se aplica cuando el cinemómetro mide desde un vehículo en movimiento. Si está parado o sobre trípode, aunque cambie de ubicación, es instalación estática (5 %).","a":"Orden ICT/155/2020, anexo XII (doctrina del Tribunal Supremo)","f":"Norma: Orden ICT/155/2020 y jurisprudencia del TS. OJO: el temario llama «radares móviles (7 %)» a los estacionarios"},
  {"id":"T15-123","p":"Según la Orden ICT/155/2020, ¿qué error máximo permitido en verificación periódica se aplica a un etilómetro evidencial para concentraciones superiores a 0,40 mg/l (y hasta 2 mg/l)?","o":["7,5 %","0,03 mg/l","5 %","10 %"],"e":"Errores máximos en verificación periódica de etilómetros: hasta 0,40 mg/l, 0,03 mg/l; de más de 0,40 a 2 mg/l, el 7,5 %.","a":"Orden ICT/155/2020, anexo XIII","f":"Norma: Orden ICT/155/2020"},
  {"id":"T15-124","p":"Si a la lectura del etilómetro se le resta el error máximo permitido del 7,5 %, ¿a partir de qué lectura considera tu temario cometido el delito por tasa (más de 0,60 mg/l) en ambas pruebas?","o":["0,66 mg/l","0,60 mg/l","0,61 mg/l","0,70 mg/l"],"e":"Criterio del temario: al menos 0,66 mg/l en ambas pruebas. Aplicando el 7,5 %, 0,66 × 0,925 ≈ 0,61 mg/l, que ya supera los 0,60 mg/l del art. 379.2 CP.","a":"Art. 379.2 CP y Orden ICT/155/2020, anexo XIII","f":"Temario del alumno (criterio operativo) + Orden ICT/155/2020"},
  {"id":"T15-125","p":"Según la Instrucción 3/2006 de la Fiscalía General del Estado, con una tasa de entre 0,40 y 0,60 mg/l en aire espirado puede apreciarse el delito del artículo 379.2 CP si concurren, entre otras, estas circunstancias:","o":["Síntomas de embriaguez, conducción peligrosa o descuidada, o haber provocado un accidente","Que el conductor sea profesional o novel","Que la prueba se haga en un control preventivo","Que el conductor no tenga antecedentes"],"e":"La Instrucción 3/2006 FGE (3 de julio) indica que en esa franja deben valorarse los síntomas de embriaguez, la comisión de infracciones o conducción peligrosa y la causación de un accidente para acreditar la influencia del alcohol.","a":"Instrucción FGE 3/2006 y art. 379.2, párrafo primero, CP","f":"Instrucción FGE 3/2006 (verificada en fuente secundaria) y temario"},
  {"id":"T15-126","p":"Según la Circular 10/2011 de la Fiscalía General del Estado, para apreciar el delito por tasa del art. 379.2 CP (más de 0,60 mg/l), la tasa típica debe:","o":["Estar presente en las dos pruebas del test de alcoholemia","Alcanzarse solo en la primera prueba","Alcanzarse solo en la prueba de contraste en sangre","Superarse en al menos una de las dos pruebas"],"e":"Según la Circular 10/2011 FGE (17 de noviembre), la tasa de más de 0,60 mg/l debe darse en las dos pruebas. Si una no la alcanza, no se aplica el inciso segundo del 379.2, salvo que exista influencia en la conducción.","a":"Circular FGE 10/2011 y art. 379.2, párrafo segundo, CP","f":"Temario del alumno (Circular FGE 10/2011)"},
  {"id":"T15-127","p":"¿Qué norma regula a nivel penal la remisión de muestras (y su cadena de custodia) al Instituto Nacional de Toxicología y Ciencias Forenses, por ejemplo en la prueba de contraste en sangre?","o":["La Orden JUS/1291/2010, de 13 de mayo","La Orden ICT/155/2020, de 7 de febrero","La Orden JUS/1234/2010, de 13 de mayo","La Instrucción 12/TV-73 de la DGT"],"e":"La Orden JUS/1291/2010, de 13 de mayo, aprueba las normas para la preparación y remisión de muestras objeto de análisis por el INTCF, incluida la cadena de custodia. En el ámbito administrativo, el temario cita la Instrucción 12/TV-73 de la DGT.","a":"Orden JUS/1291/2010, de 13 de mayo","f":"Texto legal (BOE-A-2010-8030)"},
  {"id":"T15-128","p":"¿Quién describió la curva de alcoholemia y en qué momento alcanza el alcohol su nivel máximo en sangre, según tu temario?","o":["Widmark; entre 30 y 90 minutos después de la ingesta","Widmark; a las 3 horas de la ingesta","Doppler; entre 10 y 30 minutos después de la ingesta","Widmark; inmediatamente tras la ingesta"],"e":"La curva de alcoholemia de Widmark tiene tres fases: absorción, distribución o meseta y eliminación. El máximo se alcanza entre 30 y 90 minutos después de la ingesta.","a":"Temario, art. 379.2 (curva de Widmark)","f":"Temario del alumno"},
  {"id":"T15-129","p":"¿Cómo funciona un cinemómetro de tramo y por qué no lo detectan los detectores de radar?","o":["Usa dos cámaras con reconocimiento de matrícula que calculan la velocidad media; no emite señal, así que solo lo «avisa» un GPS con su ubicación","Emite ondas de radio por efecto Doppler, detectables con antelación","Emite pulsos láser hacia el vehículo, detectables pero no inhibibles","Usa espiras de inducción bajo el asfalto que emiten una señal de radio"],"e":"El radar de tramo usa dos cámaras separadas a distancia fija con reconocimiento de matrícula (OCR) y calcula la velocidad media. Como no emite señal, los detectores no lo localizan; solo los avisadores GPS con su posición.","a":"Temario, art. 379.1 (cinemómetros de tramo)","f":"Temario del alumno"},
  {"id":"T15-130","p":"Según la clasificación de tu temario, los delitos de los artículos 379 y 380 CP son, respectivamente:","o":["De peligro abstracto (o presunto) el 379, y de peligro concreto el 380","De peligro concreto el 379, y de peligro abstracto el 380","Ambos de resultado","Ambos de peligro concreto"],"e":"El 379 se consuma con la conducta (velocidad o alcohol/drogas) sin necesidad de un peligro real: es de peligro abstracto o presunto. El 380 exige poner en concreto peligro la vida o integridad de las personas: es de peligro concreto.","a":"Arts. 379 y 380.1 CP","f":"Temario del alumno + texto legal"}
];
